input.query:
SELECT platform, min(day) FILTER (WHERE upstack_new_customers IS NOT NULL) AS first_upstack_day, min(day) AS first_day, count(*) FILTER (WHERE upstack_new_customers IS NULL) AS null_days, count(*) FILTER (WHERE upstack_new_customers IS NOT NULL) AS nonnull_days, round(sum(spend) FILTER (WHERE upstack_new_customers IS NULL)) AS null_spend, max(day) FILTER (WHERE upstack_new_customers IS NULL) AS last_null_day FROM analytics.platform_daily GROUP BY 1;
SELECT min(day) AS first_day, max(day) AS last_day, count(*) FILTER (WHERE upstack_orders IS NULL) AS null_rows, count(*) FILTER (WHERE upstack_orders=0) AS zero_rows, count(*) FILTER (WHERE upstack_orders IS NULL AND day>='2025-05-13') AS null_after FROM analytics.google_campaign_daily;
SELECT round(sum(spend)) spend_all, round(sum(spend) FILTER (WHERE day>='2025-05-13')) spend_attr_window, round(sum(upstack_new_customer_revenue) FILTER (WHERE day>='2025-05-13')) nc_rev, round(sum(upstack_new_customer_revenue) FILTER (WHERE day>='2025-05-13')/ sum(spend) FILTER (WHERE day>='2025-05-13'),3) roas_matched, round(sum(upstack_new_customer_revenue)/sum(spend),3) roas_naive FROM analytics.google_campaign_daily;
